 const text=e.kind==='travel'?`${name} moves toward known ${e.resource} at ${where(e.target)}; this step costs ${e.cost} energy.`:e.kind==='shared'?`${name} shares a ${e.resource} sighting at ${where(e.tile)} with ${state.agents.find(a=>a.id===e.recipient)?.name||'a companion'}: ${e.amount} units last seen.`:`${name} ${e.kind==='discovered'?'marks':'updates'} a ${e.resource} waypoint at ${where(e.tile)}: ${e.amount} units seen.`;
