function observe(a){let t=tile(a.x,a.y);let pos=a.y*W+a.x;if(!a.seenTiles.includes(pos))a.seenTiles.push(pos);if(a.lastVisited!==`${state.day}:${pos}`){WorldSystems.markVisit(state,a);a.lastVisited=`${state.day}:${pos}`}noticeChanges(a);noticeItems(a,t);recordExploration(a);if(!a.observed.includes(t.type)){a.observed.push(t.type);let nouns={forest:'trees and fallen branches',grass:'soft ground and scattered leaves',berry:'small red fruit',water:'moving water',rock:'loose hard stones'};event('observation',`${a.name} notices ${nouns[t.type]} for the first time.`)}a.lastAction='Observing the '+t.type}
