 const waypoints=Object.values(data.waypoints).sort((x,y)=>Number(y.amount>=(y.resource==='food'?3:6))-Number(x.amount>=(x.resource==='food'?3:6))||y.day-x.day||x.tile-y.tile||x.resource.localeCompare(y.resource));
