function regrowthHint(t){const r=WorldSystems.regrowthStatus(t);if(!r)return '';if(r.state==='cooldown')return `food regrowth in ${r.days} ${r.days===1?'day':'days'}`;if(r.state==='growing')return `expected +1 food next day · full yield in ${r.days} ${r.days===1?'day':'days'}`;return 'natural food at full yield'}
