function renderMap(){let target=$('#world-map');target.style.gridTemplateColumns=`repeat(${W},1fr)`;target.style.gridTemplateRows=`repeat(${H},1fr)`;$('.map-area').style.height=`${Math.min(650,Math.max(400,H*45))}px`;$('.map-coord').textContent=`${W} × ${H} HABITAT`;target.classList.toggle('dense',W>10);target.innerHTML=state.tiles.map((t,i)=>{let explored=state.explored.includes(i),claims=Object.entries(t.territory||{}).sort((a,b)=>b[1]-a[1]),clan=claims.length?state.clans.find(c=>c.id===Number(claims[0][0])):null,classes=['tile',t.type,explored?'':'unseen',t.visits>=3?'trodden':'',t.visits>=9?'path':'',t.structures.length?'built':'',clan?'claimed':'',selectedTile===i?'selected':'',hotspotPath.includes(i)?'waypoint-route':''].filter(Boolean).join(' '),items=t.items.filter(o=>o.quantity>0);return `<div class="${classes}" data-tile="${i}" role="button" tabindex="0" aria-label="Select tile ${i%W+1}, ${Math.floor(i/W)+1}" style="${clan?`--territory-color:${clan.color};`:''}" title="${explored?`${t.type} · ${WorldSystems.available(t,'food')} food · ${WorldSystems.available(t,'water')} water`:'Unexplored ground'} · (${i%W+1}, ${Math.floor(i/W)+1})">${hotspotMarker(i)}${explored&&t.visits>=3?'<span class="map-track"></span>':''}${explored&&t.structures.length?`<span class="structure-stack" title="${esc(t.structures.map(b=>b.name).join(', '))}">${esc(t.structures[t.structures.length-1].icon)}<small>${t.structures.length>1?t.structures.length:''}</small></span>`:''}${items.length?`<span class="item-stack" title="${esc(items.map(o=>o.name+' × '+o.quantity).join(', '))}">✧<small>${items.reduce((n,o)=>n+o.quantity,0)}</small></span>`:''}</div>`}).join('');target.querySelectorAll('[data-tile]').forEach(el=>{el.onclick=()=>{selectedTile=Number(el.dataset.tile);$('#map-caption').textContent=tileSummary(selectedTile);target.querySelectorAll('.tile').forEach(t=>t.classList.toggle('selected',t===el))};el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.onclick()}}});for(let a of living()){let el=document.createElement('button');el.type='button';el.className='agent-marker '+(a.id===1?'adam':a.id===2?'eve':'child')+(a.clanId?' clanned':'');el.style.left=`${(a.x+.5)/W*100}%`;el.style.top=`${(a.y+.5)/H*100}%`;let clan=state.clans.find(c=>c.id===a.clanId);if(clan)el.style.setProperty('--clan-color',clan.color);el.textContent=a.name[0];el.title=a.name+(clan?' · '+clan.name:'')+' · '+a.lastAction;el.setAttribute('aria-label','Inspect '+a.name);el.onclick=()=>openAgent(a.id);target.append(el)}for(const c of state.clans.filter(c=>c.members.length)){let el=document.createElement('div');el.className='clan-pin';el.style.left=`${(c.x+.5)/W*100}%`;el.style.top=`${(c.y+.15)/H*100}%`;el.style.setProperty('--clan-color',c.color);el.title=c.name;el.textContent=c.name.replace(' Clan ',' · ');target.append(el)}}
function renderFeed(){let arr=filter==='agent'?state.events.filter(e=>e.type==='speech'&&e.who?.endsWith(' ✦')):filter==='all'?state.events:state.events.filter(e=>e.type===filter);$('#activity-feed').innerHTML=arr.slice(-30).reverse().map(e=>`<div class="event ${e.type}"><div class="event-time">D${String(e.day).padStart(2,'0')}</div><div class="event-body"><div class="event-type">${e.type==='speech'?'● CONVERSATION':e.type==='observer'?'◌ OBSERVER TALK':e.type.toUpperCase()}</div><p>${e.type==='speech'||e.type==='observer'?`<strong>${esc(e.who)}</strong> <q>${esc(e.text)}</q>`:esc(e.text)}</p></div></div>`).join('') || (filter==='agent'?'<p class="feed-empty">No AI agent dialogue yet. Select HEAR AGENTS ✦ to listen.</p>':'');$('#event-count').textContent=filter==='agent'?arr.length+' AGENT LINES':state.events.length+' EVENTS';$('#filter-btn').innerHTML=(filter==='agent'?'AGENT CHAT':filter==='all'?'ALL EVENTS':filter.toUpperCase())+' <span>⌄</span>'}
