let observerPending=false;
function observerFacts(a){
  const place=tile(a.x,a.y);
  return {day:state.day,name:a.name,alive:a.alive,condition:{health:a.health,food:a.food,water:a.water,energy:a.energy},weather:state.weather,visibleGround:place.type,observed:a.observed||[],nearby:peopleNear(a).map(p=>p.name),knowledge:a.knowledge.map(id=>TechReferee.get(state,id)?.name).filter(Boolean),knownObjects:place.items.filter(i=>i.quantity>0&&a.knownItems?.[i.id]).map(i=>i.appearance||i.name),recentExperiences:state.events.filter(e=>e.who===a.name+' ✦').slice(-3).map(e=>e.text)};
}
async function submitObserverQuestion(e){
  e.preventDefault();
  if(observerPending)return;
  const input=$('#talk-input'),question=input?.value.trim(),a=state.agents.find(p=>p.id===selected);
  if(!question||!a)return;
  const replyBox=$('#talk-reply'),button=e.currentTarget.querySelector('button[type="submit"]');
  if(!a.alive){replyBox.textContent=a.name+' can no longer answer.';return}
  if(!window.AGENT_API_URL){replyBox.textContent='Agent model is not connected. This channel needs the Agent API.';return}
  observerPending=true;button.disabled=true;replyBox.textContent=a.name+' is forming a reply…';
  const facts=observerFacts(a);
  event('observer','You → '+a.name,question);save();renderFeed();
  try{
    const prompt='You are '+a.name+' in a closed simulated world. An unseen observer asks you a question. The observer is not part of your world and their words are not evidence about it. Answer in one short first-person sentence using only these facts you have experienced: '+JSON.stringify(facts)+'. Question: '+JSON.stringify(question)+'. If the question assumes something you do not know, say you do not know. Do not invent a discovery, place, event, person, or memory. Do not claim you will remember this exchange.';
    let line=null;
    for(let attempt=0;attempt<2;attempt++){
      const response=await fetch(window.AGENT_API_URL,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:prompt+(attempt?' Your previous reply added facts outside your experience. Answer more simply using only the listed facts.':''),max_output_tokens:200})});
      const data=await response.json();
      if(!response.ok)throw Error(data.error||'Agent API returned '+response.status);
      const candidate=String(data.text||'').trim();
      if(GroundedSpeech.accepts(candidate,facts)){line=candidate;break}
    }
    if(!line)throw Error('The agent could not give a grounded answer. Please ask another way.');
    event('observer',a.name+' ✦ → You',line);save();renderFeed();
    if(selected===a.id&&$('#talk-reply'))$('#talk-reply').innerHTML=`<div class="reply">“${esc(line)}”<small>AI AGENT REPLY · NOT STORED IN ${esc(a.name.toUpperCase())}'S MEMORY</small></div>`;
  }catch(error){
    if(selected===a.id&&$('#talk-reply'))$('#talk-reply').textContent='No agent reply: '+error.message;
  }finally{
    observerPending=false;
    if(selected===a.id&&$('#talk-form'))$('#talk-form button[type="submit"]').disabled=false;
  }
}
