function about(){modal(`<div class="kicker">ABOUT THE EXPERIMENT</div><h2>A world with no win state.</h2><p>Adam and Eve begin with no map, recipes, or outside facts. They observe their surroundings, gather resources, and share discoveries by speaking. Their needs, relationships, and decisions create a record you can inspect.</p><div class="modal-grid"><div><strong>INHERITANCE</strong><span>Six traits come from each parent, with an 8% chance of mutation per trait. Both parents must feel close and have enough supplies for a birth.</span></div><div><strong>KNOWLEDGE</strong><span>A hidden referee evaluates experiments with observed materials. New inventions appear as a dependency graph shaped by what people actually discover and share.</span></div><div><strong>OBSERVER CHANNEL</strong><span>Speak to a person without changing their memory. You can also describe a world change freely; referees interpret it into a visible effect.</span></div><div><strong>THIS VERSION</strong><span>Agent chat, observer replies, and ten rule referees use the connected model API. Referees also propose grounded ways to make discoveries, relationships, and consequences clearer to observe.</span></div></div><button id="reset-btn" class="outline-button" style="background:#23412d;border:0;margin-top:23px">BEGIN A NEW WORLD</button>`);$('#reset-btn').onclick=beginNewGame}
function lineage(){let gens=[...new Set(state.agents.map(a=>a.gen))].sort((a,b)=>a-b);modal(`<div class="kicker">THE FAMILY RECORD</div><h2>Lineage</h2><p>Every new person inherits six character traits from each parent. Each trait can change through an 8% mutation chance.</p><div class="lineage-tree">${gens.map(g=>`<div class="lineage-gen"><div class="lineage-label">GENERATION ${String(g).padStart(2,'0')}</div><div class="lineage-members">${state.agents.filter(a=>a.gen===g).map(a=>`<div class="lineage-node">${esc(a.name)}${a.alive?'':' †'}<small>${a.parents.length?'FROM '+a.parents.map(id=>esc(state.agents.find(p=>p.id===id)?.name||'?')).join(' + '):'FOUNDER'}</small></div>`).join('')}</div></div>`).join('')}</div>`)}
function clanRecord(){let clans=state.clans;modal(`<div class="kicker">SOCIAL GEOGRAPHY</div><h2>Clans & places</h2><p>Clans form when three or more living people maintain strong mutual ties. Their journeys gradually mark the ground they use. A clan can dissolve if its members no longer remain connected.</p><div class="lineage-tree">${clans.length?clans.map(c=>`<div class="clan-record" style="border-left:4px solid ${c.color}"><strong>${esc(c.name)}</strong><span>FORMED DAY ${c.founded} · ${c.members.length} LIVING MEMBERS · CENTRE (${c.x+1}, ${c.y+1})</span><p>${c.members.map(id=>esc(state.agents.find(a=>a.id===id)?.name||'?')).join(', ')||'No active members'}</p></div>`).join(''):'<p>No clan has formed yet. Relationships and shared survival may bring one together.</p>'}</div>`)}
function overseer(){if(selectedTile==null){let a=living()[0];selectedTile=a?a.y*W+a.x:Math.floor(state.tiles.length/2)}let t=state.tiles[selectedTile];modal(`<div class="kicker">OVERSEER / WORLD EDICT</div><h2>Describe what happens.</h2><p>Your authority is unrestricted. Describe a change in ordinary language. The referees translate it into a saved world effect; the people notice only what they can sense. Selected place: (${selectedTile%W+1}, ${Math.floor(selectedTile/W)+1}) · ${esc(t.type)}.</p><form id="overseer-form" class="overseer-form"><label>WORLD CHANGE<textarea name="description" maxlength="600" rows="5" placeholder="A glass tower appears beside the trees.&#10;Remove all food from the world.&#10;Heal Eve.&#10;Make it rain for 12 days." required></textarea></label><p class="form-help">Recognized changes alter resources, terrain, weather, or a person. Other descriptions become a persistent unfamiliar presence that inhabitants can encounter. The interpretation is shown before you apply it.</p><div id="edict-preview" class="edict-preview" aria-live="polite">Describe a change to see how the referees will enact it.</div><button class="primary-button" type="submit">ENACT IN WORLD ↗</button><div id="overseer-feedback" aria-live="polite"></div></form>`);let form=$('#overseer-form'),input=form.elements.namedItem('description'),preview=$('#edict-preview');input.oninput=()=>{try{preview.textContent=WorldInterpreter.interpret(state,input.value,selectedTile).interpretation}catch(e){preview.textContent='Describe a change to see how the referees will enact it.'}};form.onsubmit=async e=>{e.preventDefault();const submit=form.querySelector('button[type="submit"]');submit.disabled=true;$('#overseer-feedback').textContent='Ten model referees are reviewing…';try{let plan=WorldInterpreter.interpret(state,input.value,selectedTile),ruling=await councilDecision({kind:'edict',plan,label:plan.description});save();if(!ruling.approved)throw Error(ruling.votes.find(v=>v.vote==='block')?.reason||'The referees could not represent this change.');let result=WorldSystems.enact(state,plan);event('overseer',result.text);if(result.killed)event('death',`${state.agents.find(a=>a.id===plan.effect.targetId)?.name} dies after a sudden change in the world.`);for(const a of living())noticeChanges(a);save();render();$('#overseer-feedback').textContent=`Enacted: ${plan.interpretation}. ${plan.perception}`;input.value='';preview.textContent='Describe another change to see how it will be enacted.'}catch(error){$('#overseer-feedback').textContent=error.message}finally{submit.disabled=false}}}
const openOverseer=overseer;
overseer=function(){openOverseer();const form=$('#overseer-form'),input=form?.elements.namedItem('description');if(!form||!input)return;const choices=document.createElement('div');choices.className='observer-choices';choices.innerHTML='<span>QUICK INFLUENCES</span><button type="button" data-edict="Bring rain for 3 days">BRING RAIN</button><button type="button" data-edict="Place 3 berries here">SEED FOOD</button><button type="button" data-edict="Place 3 water here">LEAVE WATER</button><button type="button" data-edict="Make this ground a forest">GROW FOREST</button>';form.prepend(choices);choices.querySelectorAll('[data-edict]').forEach(button=>button.onclick=()=>{input.value=button.dataset.edict;input.dispatchEvent(new Event('input'))})};
async function connectSourceCouncil(){try{let response=await fetch('/__source-council/status',{cache:'no-store'}),data=await response.json();if(!data.connected)return;sourceCouncilConnected=true;sourceCouncilMode=data.mode||'procedural';Object.assign(RealismRules,data.rules||{});$('#restart-server-btn').hidden=sourceCouncilMode!=='codex'}catch{sourceCouncilConnected=false;$('#restart-server-btn').hidden=true}}
let developmentPending=false;
async function reviewDevelopment(){
 if(developmentPending)return;
 const world=state,existing=DevelopmentCouncil.ensure(world).reviews.find(r=>r.day===world.day&&r.status==='complete');
 if(existing)return;
 developmentPending=true;
 try{
  await DevelopmentCouncil.review(world,async(prompt)=>{
   if(!window.AGENT_API_URL)throw Error('Agent API is not connected.');
   const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),30000);
   try{const response=await fetch(window.AGENT_API_URL,{method:'POST',headers:{'Content-Type':'application/json'},signal:controller.signal,body:JSON.stringify({prompt,max_output_tokens:1000,purpose:'development'})});const result=await response.json();if(!response.ok)throw Error(result.error||'Development review failed.');return result.text}finally{clearTimeout(timeout)}
  },()=>{if(state===world){save();render();if($('#development-record'))developmentRecord()}});
 }finally{developmentPending=false;if(state===world){save();render();if($('#development-record'))developmentRecord()}}
}
function developmentRecord(){
 const reviews=DevelopmentCouncil.ensure(state).reviews,latest=reviews.at(-1),complete=reviews.some(r=>r.day===state.day&&r.status==='complete'),brief=latest?.consensus;
 modal(`<div id="development-record"><div class="kicker">GAME DEVELOPMENT / SINGLE SOURCE</div><h2>Next world update</h2><p>This is the only game-development recommendation. Ten specialist views are combined internally into this one prioritized brief.</p><button id="review-development" class="outline-button" ${developmentPending||dayPending||complete?'disabled':''}>${developmentPending?'REVIEWING…':complete?'CURRENT DAY REVIEWED':'REVIEW CURRENT DAY'}</button>${latest?`<div class="drawer-section"><h3>DAY ${latest.day} · ${esc(latest.status.toUpperCase())}</h3>${brief?`<div class="development-brief ${brief.status==='suggestion'?'actionable':''}"><div class="brief-kicker">${esc(brief.status==='suggestion'?'IMPLEMENT THIS UPDATE':brief.status==='unavailable'?'REVIEW UNAVAILABLE':'NO SUPPORTED UPDATE YET')}</div>${brief.title?`<h3>${esc(brief.title)}</h3>`:''}${brief.problem?`<p><strong>Problem:</strong> ${esc(brief.problem)}</p>`:''}${brief.playerExperience?`<p><strong>Player experience:</strong> ${esc(brief.playerExperience)}</p>`:''}<p><strong>Evidence:</strong> ${esc(brief.evidence)}</p>${brief.status==='suggestion'?`<p><strong>Change:</strong> ${esc(brief.change)}</p><p><strong>Implementation:</strong> ${esc(brief.implementation)}</p><p><strong>Acceptance check:</strong> ${esc(brief.validation)}</p><span class="brief-priority">PRIORITY · ${esc(brief.priority||'unspecified')}</span>`:''}</div>`:'<p>The combined review is in progress.</p>'}</div>`:'<p>No implementation brief yet. Advance a day or select Review current day.</p>'}</div>`);
 $('#review-development').onclick=()=>reviewDevelopment();
}
function councilRecord(){Council.ensure(state);let c=state.council;modal(`<div class="kicker">WORLD COUNCIL / EVENT RULINGS</div><h2>What was allowed?</h2><p>This record contains only rulings on events inside the simulation. Game-development guidance appears only in Development.</p><div class="council-stats"><strong>${c.approved} allowed</strong><strong>${c.blocked} blocked</strong></div><div class="trial-record">${c.decisions.slice(-20).reverse().map(d=>`<details class="council-decision"><summary><span>Day ${d.day} · ${esc(d.label)} · ${d.mode==='model'?'MODEL VOTE':d.mode==='safeguard'?'PHYSICAL SAFEGUARD':'OLDER RULE VOTE'}</span><strong>${d.approved?'ALLOWED':'BLOCKED'}</strong></summary>${d.votes.map(v=>`<div class="fact-row"><span>${esc(v.name)} · ${esc(v.reason)}</span><span>${v.vote.toUpperCase()}</span></div>`).join('')}</details>`).join('')||'<p class="tech-empty">The council has not reviewed an event yet. Step the world forward.</p>'}</div>`)}
function techTree(){let nodes=state.tech.nodes, depth=id=>{let n=TechReferee.get(state,id);return n?.parents?.length?1+Math.max(...n.parents.map(depth)):0},levels=[...new Set(nodes.map(n=>depth(n.id)))].sort((a,b)=>a-b);modal(`<div class="kicker">THE HIDDEN REFEREE'S RECORD</div><h2>Emergent technology</h2><p>No full tree is shown in advance. People test materials they have observed and carry. A successful experiment becomes a node; later inventions can depend on it. These are the paths this world has actually taken.</p><div class="tech-graph">${nodes.length?levels.map(level=>`<div class="tech-level"><div class="lineage-label">${level===0?'FIRST EXPERIMENTS':'DEPENDENCY DEPTH '+level}</div><div class="tech-nodes">${nodes.filter(n=>depth(n.id)===level).map(n=>`<div class="tech-node"><span>DAY ${String(n.day).padStart(2,'0')} · ${esc(n.discoverer)}</span><strong>${esc(n.name)}</strong><p>${esc(n.detail)}</p><small>${n.parents.length?'BUILT FROM '+n.parents.map(id=>esc(TechReferee.get(state,id)?.name||'an earlier finding')).join(' + '):'TESTED '+n.materials.map(esc).join(' + ')}</small></div>`).join('')}</div></div>`).join(''):'<p class="tech-empty">No successful experiments yet. Let the world run to see its first branch.</p>'}</div><div class="trial-record"><div class="lineage-label">RECENT EXPERIMENTS</div>${state.tech.trials.slice(-8).reverse().map(t=>`<div class="fact-row"><span>Day ${t.day} · ${esc(t.person)} tried ${esc(t.method)} (${t.materials.map(esc).join(', ')})</span><span>${t.result.toUpperCase()}</span></div>`).join('')||'<p class="tech-empty">The inhabitants have not experimented yet.</p>'}</div>`)}
